CREATE DEFINER=`CUP_admin`@`%` PROCEDURE `sp_insert_missing_values`(in missing_year bigint(4))
BEGIN

set @info = concat('Stored procedure - added missing value for ', missing_year);

# Redo the process
drop table if exists indicators_countries_missing_values;

# Find the indicators which are missing the values for the year in question
create table indicators_countries_missing_values as 
select distinct iv1.country_code, i1.no_of_indicator, i1.name_of_indicator, i1.indicator_origin_type, i1.extracted_from_file_type
from indicators_values iv1
join indicators i1 on (i1.indicator_id = iv1.indicator_id)
where 1=1
and not exists 
(select * 
 from indicators_values iv2 join indicators i2 on (i2.indicator_id = iv2.indicator_id)
 where i1.no_of_indicator = i2.no_of_indicator
 and i1.indicator_origin_type = i2.indicator_origin_type
 and i1.extracted_from_file_type = i2.extracted_from_file_type
 and iv1.country_code = iv2.country_code
 and iv2.year = missing_year)
limit 100000;

# See what we found
select * from indicators_countries_missing_values order by no_of_indicator asc, country_code asc;

# To be consistent and not make the wrong link between new indicators_values for 2014 and indicators table, add indicator(s) first
INSERT INTO indicators
(
`no_of_indicator`,
`name_of_indicator`,
`additional_info`,
`indicator_origin_type`,
`extracted_from_file_type`,
`extracted_from_file_year`
)
select distinct no_of_indicator, name_of_indicator, @info, indicator_origin_type, extracted_from_file_type, missing_year from indicators_countries_missing_values;

# Add indicators values linking them to newly added indicators
INSERT INTO indicators_values
(
`year`,
`indicator_id`,
`country_code`,
`value`,
`additional_info`
)
select missing_year, i.indicator_id, country_code, if(i.indicator_origin_type = 'raw', 'NA', 'not computable'), @info
from indicators_countries_missing_values im 
join indicators i on (i.no_of_indicator = im.no_of_indicator and i.extracted_from_file_year = missing_year) 
where 1=1;

# Clean up after yourself
drop table if exists indicators_countries_missing_values;

END ;;
DELIMITER ;
